import type { AppLanguage } from './types';

/**
 * Main-process error sentences that reached non-Spanish readers in Spanish.
 *
 * The app already had two ways to keep an Electron error out of a foreign-language
 * interface, and both had the same blind spot. `localizeRuntimeError` translates the
 * messages it recognises; everything else it hands to `looksLikeSpanishUiText`, and
 * whatever that detector calls Spanish collapses into the generic "the operation could
 * not be completed". The detector is deliberately conservative — it wants two Spanish
 * function words, a diacritic or a term from a short vocabulary — so a large family of
 * short, accent-free error sentences ("La nota no existe.", "El adjunto ya no existe.",
 * "Escribe una pregunta.") passed every check and arrived verbatim: Spanish prose in an
 * English, French, German, Portuguese, Italian or Turkish window.
 *
 * A sweep of every `new Error(...)` literal in electron/ and shared/ — 1,521 of them — run
 * through `localizeRuntimeError` in each of the seven languages, found two failures side by
 * side: 146 sentences that arrived verbatim in Spanish, and 1,051 that the detector caught
 * and replaced with the generic line, which is not a leak but erases the one thing the
 * message existed to say. Both sets are here, along with a dozen more carried as
 * `message`/`error` payload fields. Widening the detector would only have converted the
 * first failure into the second.
 *
 * Spanish is not stored: the caller supplies `es` from the original message, so the source
 * sentence stays the single source of truth and cannot drift from the key.
 *
 * scripts/test-main-error-i18n.mjs re-runs the sweep and fails on any new leak.
 */
export type MainErrorTranslations = Partial<Record<AppLanguage, string>> & { en: string };

/** Messages whose text is fixed, matched exactly. */
