  'El catálogo de precios de Cloudflare no tiene un formato compatible.': { en: 'The Cloudflare price catalogue is not in a compatible format.', fr: 'Le catalogue tarifaire de Cloudflare n’a pas un format compatible.', de: 'Der Cloudflare-Preiskatalog hat kein kompatibles Format.', pt: 'O catálogo de preços da Cloudflare não tem um formato compatível.', 'pt-BR': 'O catálogo de preços da Cloudflare não tem um formato compatível.', it: 'Il catalogo prezzi di Cloudflare non ha un formato compatibile.', tr: 'Cloudflare fiyat kataloğu uyumlu bir biçimde değil.' },
  'La configuración del catálogo de Cloudflare no es compatible.': { en: 'The Cloudflare catalogue configuration is not compatible.', fr: 'La configuration du catalogue Cloudflare n’est pas compatible.', de: 'Die Konfiguration des Cloudflare-Katalogs ist nicht kompatibel.', pt: 'A configuração do catálogo da Cloudflare não é compatível.', 'pt-BR': 'A configuração do catálogo da Cloudflare não é compatível.', it: 'La configurazione del catalogo di Cloudflare non è compatibile.', tr: 'Cloudflare katalog yapılandırması uyumlu değil.' },
