  'Para instalar whisper.cpp con un clic se necesita Homebrew. Instálalo y vuelve a intentarlo.': { en: 'One-click installation of whisper.cpp needs Homebrew. Install it and try again.', fr: 'L’installation en un clic de whisper.cpp nécessite Homebrew. Installez-le et réessayez.', de: 'Die Ein-Klick-Installation von whisper.cpp benötigt Homebrew. Installieren Sie es und versuchen Sie es erneut.', pt: 'Para instalar o whisper.cpp com um clique é necessário o Homebrew. Instale-o e tente de novo.', 'pt-BR': 'Para instalar o whisper.cpp com um clique é necessário o Homebrew. Instale-o e tente novamente.', it: 'L’installazione con un clic di whisper.cpp richiede Homebrew. Installalo e riprova.', tr: 'whisper.cpp’yi tek tıkla kurmak için Homebrew gerekir. Kurup yeniden deneyin.' },
  'whisper.cpp se instaló, pero no se encontró whisper-cli. Reinicia Nodus y vuelve a comprobarlo.': { en: 'whisper.cpp was installed, but whisper-cli was not found. Restart Nodus and check again.', fr: 'whisper.cpp a été installé, mais whisper-cli est introuvable. Redémarrez Nodus et vérifiez à nouveau.', de: 'whisper.cpp wurde installiert, aber whisper-cli wurde nicht gefunden. Starten Sie Nodus neu und prüfen Sie erneut.', pt: 'O whisper.cpp foi instalado, mas não se encontrou o whisper-cli. Reinicie o Nodus e verifique de novo.', 'pt-BR': 'O whisper.cpp foi instalado, mas não se encontrou o whisper-cli. Reinicie o Nodus e verifique novamente.', it: 'whisper.cpp è stato installato, ma whisper-cli non è stato trovato. Riavvia Nodus e ricontrolla.', tr: 'whisper.cpp kuruldu ancak whisper-cli bulunamadı. Nodus’u yeniden başlatıp tekrar denetleyin.' },
  'La desinstalación automática de whisper.cpp todavía no está disponible en este sistema.': { en: 'Automatic uninstallation of whisper.cpp is not available on this system yet.', fr: 'La désinstallation automatique de whisper.cpp n’est pas encore disponible sur ce système.', de: 'Die automatische Deinstallation von whisper.cpp ist auf diesem System noch nicht verfügbar.', pt: 'A desinstalação automática do whisper.cpp ainda não está disponível neste sistema.', 'pt-BR': 'A desinstalação automática do whisper.cpp ainda não está disponível neste sistema.', it: 'La disinstallazione automatica di whisper.cpp non è ancora disponibile su questo sistema.', tr: 'whisper.cpp’nin otomatik kaldırılması bu sistemde henüz kullanılamıyor.' },
  'No se encontró Homebrew para desinstalar whisper.cpp.': { en: 'Homebrew was not found to uninstall whisper.cpp.', fr: 'Homebrew est introuvable pour désinstaller whisper.cpp.', de: 'Homebrew wurde nicht gefunden, um whisper.cpp zu deinstallieren.', pt: 'Não se encontrou o Homebrew para desinstalar o whisper.cpp.', 'pt-BR': 'Não se encontrou o Homebrew para desinstalar o whisper.cpp.', it: 'Homebrew non è stato trovato per disinstallare whisper.cpp.', tr: 'whisper.cpp’yi kaldırmak için Homebrew bulunamadı.' },
  'La descarga del modelo whisper.cpp quedó vacía.': { en: 'The whisper.cpp model download came back empty.', fr: 'Le téléchargement du modèle whisper.cpp est resté vide.', de: 'Der Download des whisper.cpp-Modells blieb leer.', pt: 'A transferência do modelo whisper.cpp ficou vazia.', 'pt-BR': 'O download do modelo whisper.cpp ficou vazio.', it: 'Il download del modello whisper.cpp è risultato vuoto.', tr: 'whisper.cpp modeli indirmesi boş döndü.' },
  'whisper.cpp no está instalado. Instálalo desde Ajustes.': { en: 'whisper.cpp is not installed. Install it from Settings.', fr: 'whisper.cpp n’est pas installé. Installez-le depuis les Réglages.', de: 'whisper.cpp ist nicht installiert. Installieren Sie es in den Einstellungen.', pt: 'O whisper.cpp não está instalado. Instale-o nas Definições.', 'pt-BR': 'O whisper.cpp não está instalado. Instale-o nas Configurações.', it: 'whisper.cpp non è installato. Installalo dalle Impostazioni.', tr: 'whisper.cpp kurulu değil. Ayarlar’dan kurun.' },
  'whisper.cpp no devolvió texto para este audio.': { en: 'whisper.cpp returned no text for this audio.', fr: 'whisper.cpp n’a renvoyé aucun texte pour cet audio.', de: 'whisper.cpp hat für diese Audiodatei keinen Text zurückgegeben.', pt: 'O whisper.cpp não devolveu texto para este áudio.', 'pt-BR': 'O whisper.cpp não retornou texto para este áudio.', it: 'whisper.cpp non ha restituito testo per questo audio.', tr: 'whisper.cpp bu ses için metin döndürmedi.' },

