/**
 * The detail half of a local-provider connection failure.
 *
 * `localError` in electron/ai/providers.ts composes "could not connect" + a detail, and
 * the detail is either one of two Spanish hints or raw transport output (`fetch failed`,
 * `The operation was aborted`). Transport output is not ours to translate and stays
 * verbatim in every language — it is the part a user pastes into a bug report.
 */
function localProviderDetail(detail: string): MainErrorTranslations | null {
  const ollama = /^HTTP (\d+)\. ¿Está Ollama en marcha\?$/.exec(detail);
  if (ollama) {
    const [, status] = ollama;
    return { en: `HTTP ${status}. Is Ollama running?`, fr: `HTTP ${status}. Ollama est-il en cours d’exécution ?`, de: `HTTP ${status}. Läuft Ollama?`, pt: `HTTP ${status}. O Ollama está a correr?`, 'pt-BR': `HTTP ${status}. O Ollama está em execução?`, it: `HTTP ${status}. Ollama è in esecuzione?`, tr: `HTTP ${status}. Ollama çalışıyor mu?` };
  }
  const lmStudio = /^HTTP (\d+)\. Activa el servidor local en LM Studio\.$/.exec(detail);
  if (lmStudio) {
    const [, status] = lmStudio;
    return { en: `HTTP ${status}. Start the local server in LM Studio.`, fr: `HTTP ${status}. Démarrez le serveur local dans LM Studio.`, de: `HTTP ${status}. Starten Sie den lokalen Server in LM Studio.`, pt: `HTTP ${status}. Ative o servidor local no LM Studio.`, 'pt-BR': `HTTP ${status}. Ative o servidor local no LM Studio.`, it: `HTTP ${status}. Avvia il server locale in LM Studio.`, tr: `HTTP ${status}. LM Studio’da yerel sunucuyu başlatın.` };
  }
  return null;
}

